import { Table, BooleanColumn, GenericColumn } from '../../db'

export const sp_header_footer = Table({
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sp_widget',
    label: 'Header | Footer',
    name: 'sp_header_footer',
    schema: {
        static: BooleanColumn({
            label: [
                {
                    hint: 'Static headers and footers do not refresh theme data on each page change - keep checked for a potential performance improvement',
                    label: 'Static',
                    plural: 'Statics',
                    language: 'en',
                },
            ],
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
    },
})
